        reset_dut();

        d = 4'h7;
        @(posedge clk);
        #1;


        rst = 1;
        d = 4'hE;
        @(posedge clk);
        #1;

        #1;


        check_outputs(4'h0);
        rst = 0;
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Data Stability Check", test_num);
        reset_dut();
        d = 4'h3;
