module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);parameter A = 3'b000, B = 3'b001, C = 3'b010, D = 3'b011, E = 3'b100;
  reg [2:0] state, next_state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    match = 0;
    next_state = state;
    case (state)
      A: begin
        if (data) begin
          next_state = B;
        end
      end
      B: begin
        if (data) begin
          next_state = B;
        end else begin
          next_state = C;
        end
      end
      C: begin
        if (data) begin
          next_state = D;
        end else begin
          next_state = A;
        end
      end
      D: begin
        if (data) begin
          next_state = E;
        end else begin
          next_state = A;
        end
      end
      E: begin
        if (data) begin
          next_state = B;
          match = 1;
        end else begin
          next_state = A;
        end
      end
    endcase
  end

endmodule

