module top_module(
  input clk,
  input reset,
  input enable,
  input [n-1:0] in,
  output reg [n-1:0] state
);parameter n = 4; // number of states

// Define the state signals
reg [n-1:0] next_state;
reg [n-1:0] current_state;

// Define the transition rules
always @(*) begin
  case(current_state)
    0: next_state = {enable, 1'b0, 1'b0, 1'b0};
    1: next_state = {1'b0, enable, 1'b0, 1'b0};
    2: next_state = {1'b0, 1'b0, enable, 1'b0};
    3: next_state = {1'b0, 1'b0, 1'b0, enable};
    default: next_state = {n{1'b0}};
  endcase
end

// Update the state signals on the rising edge of the clock
always @(posedge clk) begin
  if(reset) begin
    current_state <= {n{1'b0}};
  end else if(enable) begin
    current_state <= next_state;
  end
end

// Assign the state signals to the output
assign state = current_state;

endmodule

