module top_module (
        input clk,
        input areset,
        input up,
        input down,
        input at_floor1,
        input at_floor2,
        output reg [1:0] pos);parameter Floor1=2'b00, MovingUp=2'b01, Floor2=2'b10, MovingDown=2'b11;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Floor1;
		else begin
			case (state)
				Floor1: state <= up ? MovingUp : Floor1;
				MovingUp: state <= at_floor2 ? Floor2 : MovingUp;
				Floor2: state <= down ? MovingDown : Floor2;
				MovingDown: state <= at_floor1 ? Floor1 : MovingDown;
			endcase
		end
	end

	assign pos = state;

endmodule

