description:
Implement the Verilog module based on the following description.
Module O implements the boolean function x = (g | ~h).

// Module P can be described by the following simulation waveform: 

If g = 1, h = 1, then x = 1.
If g = 0, h = 1, then x = 0.
If g = 0, h = 0, then x = 1.
If g = 1, h = 0, then x = 1.

// Now consider a top-level that uses three O submodules and one P submodule. The first input of all four submodules is connected to input 'd', and the second input of all four submodules is connected to 'e'. The output of the first O submodule is connected to a two-input OR gate with the output of the P submodule. The second and third O submodules' outputs are connected to an AND gate. The output of the OR and the AND gates are connected to a final XOR gate whose output is 'x'.

// Implement this circuit in Verilog.

module top_module(
    input d,
    input e,
    output x);

code:
module O(
    input d,
    input e,
    output x
);
    assign x = (d | ~e);
endmodule

module P(
    input d,
    input e,
    output x
);
    assign x = (d | ~e);
endmodule

module top_module(
    input d,
    input e,
    output x
);
    wire o1_out, o2_out, o3_out, p_out;
    wire or_out, and_out;

    O o1(.d(d), .e(e), .x(o1_out));
    O o2(.d(d), .e(e), .x(o2_out));
    O o3(.d(d), .e(e), .x(o3_out));
    P p1(.d(d), .e(e), .x(p_out));

    assign or_out = o1_out | p_out;
    assign and_out = o2_out & o3_out;

    assign x = or_out ^ and_out;
endmodule

