module top_module(input CLOCK_50, input [1:0] KEY, input req, output reg [7:0] value_0, output reg [7:0] value_1, output reg [7:0] value_2, output reg value_0_valid, output reg value_1_valid, output reg value_2_valid);reg ready;
    reg running;
    reg [7:0] reqCount;
    reg [24:0] timer;
    reg ack;

    initial begin
        value_0 = 8'd0;
        value_1 = 8'd0;
        value_2 = 8'd0;
        value_0_valid = 1'b0;
        value_1_valid = 1'b0;
        value_2_valid = 1'b0;
        running = 1'b0;
        reqCount = 8'd0;
        ack = 1'b0;
    end

    always @(posedge CLOCK_50) begin
        if(KEY[0]) begin
            value_0 = 8'h55;
            value_0_valid = 1'b1;
        end

        if(KEY[1]) begin
            value_1 = 8'hAA;
            value_1_valid = 1'b1;
        end

        if(running) begin
            if(ack & value_2_valid) begin
                reqCount <= 8'd0;
                value_2_valid <= 1'b0;
            end else begin
                if(req && reqCount < 10) begin
                    reqCount <= reqCount + 8'd1;
                end else if(req) begin
                    reqCount <= 8'd0;
                    value_2 <= 8'h00;
                    value_2_valid <= 1'b0;
                end
            end
        end else begin
            reqCount <= 8'd0;
            value_2_valid <= 1'b0;
        end

        timer <= timer + 25'd1;
        if(timer == 25'd0)
            running <= ~running;

        if(timer == 25'd0 && ~running) begin
            value_2_valid <= 1'b0;
        end

        if(value_2_valid && ~ack) begin
            ack <= 1'b1;
        end else if(~value_2_valid) begin
            ack <= 1'b0;
        end
    end
