module top_module(ENB, HEX);input	ENB;
	output [6:0] HEX;

	wire [3:0] V;

	assign V = 4'b0 | ENB;

	wire A = V[0];
	wire B = V[1];
	wire C = V[2];
	wire D = V[3];

	wire common = D&B | D&C;


