module top_module(
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [15:0] writedata,
  output reg [15:0] out_port,
  output reg [31:0] readdata
);localparam WORD_SIZE = 16;
  localparam WORDS_COUNT = 32768;
  localparam ADDR_BITS = $clog2(WORDS_COUNT);
  localparam MEM_DEPTH = 1 << ADDR_BITS;

  reg [ADDR_BITS-1:0] addr_reg;
  reg [WORD_SIZE-1:0] mem [0:MEM_DEPTH-1];

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      addr_reg <= 0;
      out_port <= 0;
      readdata <= 32'b0;
    end else if (chipselect) begin
      if (~write_n) begin
        mem[addr_reg] <= writedata;
      end else begin
        out_port <= mem[addr_reg];
        readdata <= {16'b0, mem[addr_reg]};
      end
      addr_reg <= address;
    end else begin
      out_port <= 0;
      readdata <= 32'b0;
    end
  end

endmodule

