module pattern_generator (
	input clk,
	input resetn,
	output pattern_out);

	parameter P0=0, P1=1, P2=2, P3=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= P0;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			P0: next_state = P1;
			P1: next_state = P2;
			P2: next_state = P3;
			P3: next_state = P0;
			default: next_state = P0;
		endcase
	end

	assign pattern_out = (state == P1) || (state == P3);
endmodule

