module top_module(CLK, RST, RIGHT, RIGHT_REG, LEFT_REG1, RIGHT_REG1);input CLK;
input RST;
input [32 : 1]RIGHT;
input [32 : 1]RIGHT_REG;
output [32 : 1] LEFT_REG1;
output [32 : 1] RIGHT_REG1;
wire CLK;
wire RST;
reg [32 : 1] LEFT_REG1;
reg [32 : 1] RIGHT_REG1;
always @ (posedge CLK or posedge RST)
