module top_module(input clk, input reset, input x, output reg out);reg state, next_state;
    parameter S0 = 0;
    parameter S1 = 1;
    always @(posedge clk or posedge reset)
      begin
        if(reset)begin
        state <= S0;
        end
       else begin
        state <= next_state;
       end
       end

  always @(x or state)
          begin
            case(state)
              S0:
                if(x)begin
                  next_state <= S1;
                  out <= 1'b1;
                end
              else begin
                next_state <= S0;
                out <= 1'b0;
              end
              S1:
                if(x)begin
                  next_state <= S1;
                  out <= 1'b0;
                end
              else begin
                next_state <= S1;
                out <= 1'b1;
              end
            endcase
