            end
            3'b100: begin // xor
                result <= A ^ B;
                zero <= (result == 0);
            end
            3'b101: begin // slt
                if (A < B) begin
                    result <= 1;
                    zero <= 0;
                end else begin
                    result <= 0;
                    zero <= 1;
