module top_module(
    input i_clk,
    input i_rst,
    input i_enable,
    input i_subtract, 
    input [7:0] i_reg_a,
    input [7:0] i_reg_b,
    output o_carry,
    output o_zero,
    output [7:0] o_result
);reg [7+1:0] out = 0;

    assign o_result = i_enable ? out[7:0] : 8'bZZ;
    assign o_carry = out[8];
    assign o_zero = out[7:0] == 8'h00;

    always @* begin
        if (~i_rst) begin
            out <= 0;
        end else begin
            if (i_subtract)
                out <= i_reg_a - i_reg_b;
            else
                out <= i_reg_a + i_reg_b;
        end
    end

endmodule

