module top_module(input rx,
                 output reg avail, 
                 output reg [7:0] dout,
                 input wire clk_div);// Define the states
    parameter RX_STATE_START = 2'b00;
    parameter RX_STATE_DATA = 2'b01;
    parameter RX_STATE_STOP = 2'b10;

    // Define the internal registers
    reg [1:0] state = RX_STATE_START;
    reg [3:0] bitpos = 0;
    reg [7:0] scratch = 8'b00000000;

    // Initialize the outputs
    initial begin
        avail = 0;
        dout = 8'b00000000;
    end

    always @(negedge clk_div) begin
        case (state)
            RX_STATE_START: begin
                // Wait for a start bit
                avail <= 0;
                if (rx == 0) begin
                    bitpos <= 0;
                    scratch <= 0;
                    state <= RX_STATE_DATA;
                end
            end

            RX_STATE_DATA: begin
                // Read in the data bits
                if (bitpos <= 7) begin
                    scratch[bitpos] <= rx;
                    bitpos <= bitpos + 1;
                end

                if (bitpos == 8) begin
                    state <= RX_STATE_STOP;
                end
            end

            RX_STATE_STOP: begin
                // Wait for a stop bit
                if (rx == 1) begin
                    state <= RX_STATE_START;
                    dout <= scratch;
                    avail <= 1;
                end
            end

            default: begin
                // Reset to RX_STATE_START on invalid input
                state <= RX_STATE_START;
            end
        endcase
    end

endmodule

module binary_counter(CLK, RST, Count);
input CLK, RST;
output [3:0] Count;
reg [3:0] Count;

always @(posedge CLK or posedge RST) begin
    if (RST)
        Count <= 0;
    else
        Count <= Count + 1;
end

endmodule

