module top_module(x, y, instr, out, eq, lt, gt);input [15:0] x;
	input [15:0] y;
	input [5:0] instr;
	output [15:0] out;
	output eq, lt, gt;

	wire [15:0] xz;
	wire [15:0] yz;
	assign xz = instr[5] ? 16'b0 : x;
	assign yz = instr[3] ? 16'b0 : y;
	wire [15:0] xf;
	wire [15:0] yf;
	assign xf = instr[4] ? ~xz : xz;
	assign yf = instr[2] ? ~yz : yz;
	wire [15:0] pResult;
	wire [15:0] aResult;
	assign pResult = xf + yf;
	assign aResult = xf & yf;
	wire [15:0] r;
	assign r = instr[1] ? pResult : aResult;
	assign out = instr[0] ? ~r : r;

	assign eq = (out == 16'b0);
	assign lt = out[15];
	assign gt = !eq & !lt;endmodule

