module top_module(
    CLK,
    RESET,
    ENABLE,
    COUNT,
    OVERFLOW
);input CLK;
    input RESET;
    input ENABLE;
    output reg [3:0] COUNT;
    output reg OVERFLOW;

    // Removed the instantiation of the undefined flip-flop. 
    // Instead, we will directly use the signals for our counting logic.

    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            COUNT <= 0;
            OVERFLOW <= 0;
        end else if (ENABLE) begin
            COUNT <= COUNT + 1;
            if (COUNT == 4'hF) begin
                OVERFLOW <= 1;
            end
        end
    end

    always @(negedge CLK) begin
        if (OVERFLOW) begin
            COUNT <= 0;
            OVERFLOW <= 0;
        end
    end

endmodule

